import React, { useState } from 'react';
import {
  Box,
  Typography,
  Button,
  TextField,
  Paper,
  Alert,
  Snackbar,
  CircularProgress,
} from '@mui/material';

const MarketingPage = () => {
  const [emailSubject, setEmailSubject] = useState('');
  const [emailBody, setEmailBody] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSendEmail = async () => {
    if (!emailSubject || !emailBody) {
      alert('Vui lòng điền đầy đủ tiêu đề và nội dung email.');
      return;
    }

    setLoading(true);
    try {
      const result = { success: true };
      if (result.success) {
        setSnackbarOpen(true);
        setEmailSubject('');
        setEmailBody('');
      } else {
        alert('Có lỗi xảy ra, vui lòng thử lại.');
      }
    } catch (error) {
      console.error('Lỗi khi gửi email:', error);
      alert('Đã xảy ra lỗi, không thể gửi email.');
    } finally {
      setLoading(false);
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h4" gutterBottom>
        Quảng cáo & Marketing
      </Typography>
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>
          Gửi Email quảng cáo
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Bạn có thể tạo và gửi các chiến dịch email marketing đến danh sách khách hàng tiềm năng.
        </Typography>
        <TextField
          label="Tiêu đề email"
          fullWidth
          margin="normal"
          value={emailSubject}
          onChange={(e) => setEmailSubject(e.target.value)}
        />
        <TextField
          label="Nội dung email"
          fullWidth
          multiline
          rows={8}
          margin="normal"
          value={emailBody}
          onChange={(e) => setEmailBody(e.target.value)}
        />
        <Button
          variant="contained"
          color="primary"
          onClick={handleSendEmail}
          sx={{ mt: 2 }}
          disabled={loading}
        >
          {loading ? <CircularProgress size={20} color="inherit" /> : 'Gửi chiến dịch'}
        </Button>
      </Paper>
      <Snackbar open={snackbarOpen} autoHideDuration={6000} onClose={handleCloseSnackbar}>
        <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
          Chiến dịch email đã được gửi thành công!
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default MarketingPage;
